package cn.iocoder.yudao.module.zsjos.dal.mysql.handover;
import cn.iocoder.yudao.framework.mybatis.core.mapper.BaseMapperX; import cn.iocoder.yudao.module.zsjos.dal.dataobject.handover.HandoverSheetDO; import org.apache.ibatis.annotations.Mapper; import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import java.util.List;
@Mapper public interface HandoverSheetMapper extends BaseMapperX<HandoverSheetDO> { default List<HandoverSheetDO> selectByParticipant(Long userId){ return selectList(new LambdaQueryWrapper<HandoverSheetDO>().and(q->q.eq(HandoverSheetDO::getFromUserId,userId).or().eq(HandoverSheetDO::getToUserId,userId).or().eq(HandoverSheetDO::getArbitratorUserId,userId)).orderByDesc(HandoverSheetDO::getUpdateTime).orderByDesc(HandoverSheetDO::getId)); } default int transition(Long id,Integer version,String from,String to){ return update(null,new com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper<HandoverSheetDO>().eq(HandoverSheetDO::getId,id).eq(HandoverSheetDO::getVersion,version).eq(HandoverSheetDO::getStatus,from).set(HandoverSheetDO::getStatus,to).set(HandoverSheetDO::getVersion,version+1)); } }
